    // Small dependency-free JSON boundary for the existing RunCommand reference set.
    // No reflection, package loading, runtime serialization of arbitrary objects.
    public class Json58 : IEnumerable<Json58>
    {
        protected Dictionary<string, Json58> fields;
        protected List<Json58> items;
        protected object value;
        public Json58 this[string key]
        {
            get
            {
                Json58 v;
                return fields != null && fields.TryGetValue(key, out v) ? v : null;
            }

            set
            {
                fields[key] = value;
            }
        }

        public Json58 this[int i]
        {
            get
            {
                return items[i];
            }
        }

        public int Count
        {
            get
            {
                return items != null ? items.Count : fields != null ? fields.Count : 0;
            }
        }

        public void Add(Json58 v)
        {
            items.Add(v);
        }

        public IEnumerable<T> Values<T>()
        {
            return this.Select(v => (T)Convert.ChangeType(v.value, typeof(T), CultureInfo.InvariantCulture));
        }

        public IEnumerator<Json58> GetEnumerator()
        {
            return (items ?? (fields == null ? new List<Json58>() : fields.Values.ToList())).GetEnumerator();
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }

        public static implicit operator Json58(string v)
        {
            return v == null ? null : new Json58{value = v};
        }

        public static implicit operator Json58(int v)
        {
