        }

        public static implicit operator Json58(bool v)
        {
            return new Json58{value = v};
        }

        public static explicit operator string (Json58 v)
        {
            return v == null ? null : Convert.ToString(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator int (Json58 v)
        {
            return Convert.ToInt32(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator long (Json58 v)
        {
            return Convert.ToInt64(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator double (Json58 v)
        {
            return Convert.ToDouble(v.value, CultureInfo.InvariantCulture);
        }

        public static explicit operator bool (Json58 v)
