            return Convert.ToBoolean(v.value, CultureInfo.InvariantCulture);
        }

        public static Json58 Wrap(object v)
        {
            if (v == null)
                return null;
            if (v is Json58)
                return (Json58)v;
            if (v is string)
                return (string)v;
            if (v is bool)
                return (bool)v;
            if (v is double)
                return (double)v;
            if (v is float)
                return (float)v;
            if (v is int)
                return (int)v;
            if (v is long)
                return (long)v;
            if (v is IEnumerable)
            {
                var a = new Arr58();
                foreach (var x in (IEnumerable)v)
                    a.Add(Wrap(x));
                return a;
            }

            throw new ArgumentException("Unsupported JSON boundary value: " + v.GetType().Name);
        }

        static string Quote(string text)
        {
            var b = new StringBuilder("\"");
            foreach (char c in text)
            {
                switch (c)
                {
                    case '"':
                        b.Append("\\\"");
                        break;
                    case '\\':
                        b.Append("\\\\");
                        break;
                    case '\b':
                        b.Append("\\b");
                        break;
                    case '\f':
                        b.Append("\\f");
                        break;
                    case '\n':
                        b.Append("\\n");
                        break;
                    case '\r':
                        b.Append("\\r");
                        break;
                    case '\t':
                        b.Append("\\t");
                        break;
                    default:
                        if (c < 32)
                            b.Append("\\u" + ((int)c).ToString("x4"));
                        else
                            b.Append(c);
                        break;
                }
            }

            return b.Append('"').ToString();
        }

        public override string ToString()
        {
            if (fields != null)
                return "{" + string.Join(",", fields.OrderBy(p => p.Key, StringComparer.Ordinal).Select(p => Quote(p.Key) + ":" + (p.Value == null ? "null" : p.Value.ToString()))) + "}";
            if (items != null)
                return "[" + string.Join(",", items.Select(v => v == null ? "null" : v.ToString())) + "]";
            if (value == null)
                return "null";
            if (value is string)
                return Quote((string)value);
            if (value is bool)
                return (bool)value ? "true" : "false";
            if (value is double)
            {
                double x = (double)value;
                if (double.IsNaN(x) || double.IsInfinity(x))
                    throw new ArgumentException("Nonfinite JSON number");
                return x.ToString("R", CultureInfo.InvariantCulture);
            }

            return Convert.ToString(value, CultureInfo.InvariantCulture);
        }

        public static bool DeepEquals(Json58 a, Json58 b)
        {
            return a == null ? b == null : b != null && a.ToString() == b.ToString();
        }

        public static Json58 Parse(string text)
        {
            int p = 0;
            var result = ParseValue(text, ref p, 0);
            Space(text, ref p);
            if (p != text.Length)
                throw new ArgumentException("Trailing JSON data");
            return result;
        }

        static void Space(string s, ref int p)
        {
            while (p < s.Length && char.IsWhiteSpace(s[p]))
                p++;
        }

        static string ParseString(string s, ref int p)
        {
            if (s[p++] != '"')
                throw new ArgumentException("JSON string expected");
            var b = new StringBuilder();
            while (p < s.Length)
            {
                char c = s[p++];
                if (c == '"')
                    return b.ToString();
                if (c == '\\')
                {
                    char e = s[p++];
                    switch (e)
                    {
                        case '"':
                        case '\\':
                        case '/':
                            b.Append(e);
                            break;
                        case 'b':
                            b.Append('\b');
                            break;
                        case 'f':
                            b.Append('\f');
                            break;
                        case 'n':
                            b.Append('\n');
                            break;
                        case 'r':
                            b.Append('\r');
                            break;
                        case 't':
                            b.Append('\t');
                            break;
                        case 'u':
                            b.Append((char)int.Parse(s.Substring(p, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                            p += 4;
                            break;
                        default:
                            throw new ArgumentException("JSON escape");
                    }
                }
                else
                {
                    if (c < 32)
                        throw new ArgumentException("JSON control character");
                    b.Append(c);
                }
            }

            throw new ArgumentException("Unterminated JSON string");
        }

        static Json58 ParseValue(string s, ref int p, int depth)
        {
            if (depth > 128)
                throw new ArgumentException("JSON nesting limit");
            Space(s, ref p);
            if (p >= s.Length)
                throw new ArgumentException("JSON value expected");
            char c = s[p];
            if (c == '"')
                return ParseString(s, ref p);
            if (c == '{' || c == '[')
            {
                bool obj = c == '{';
                p++;
                Json58 result = obj ? (Json58)new Obj58() : new Arr58();
                Space(s, ref p);
                if (p < s.Length && s[p] == (obj ? '}' : ']'))
                {
                    p++;
                    return result;
                }

                while (true)
                {
                    Space(s, ref p);
                    string key = null;
                    if (obj)
                    {
                        key = ParseString(s, ref p);
                        Space(s, ref p);
                        if (s[p++] != ':')
                            throw new ArgumentException("JSON colon");
                    }

                    var v = ParseValue(s, ref p, depth + 1);
                    if (obj)
                        result[key] = v;
                    else
                        result.Add(v);
                    Space(s, ref p);
                    char end = s[p++];
                    if (end == (obj ? '}' : ']'))
                        break;
                    if (end != ',')
                        throw new ArgumentException("JSON separator");
                }

                return result;
            }

            foreach (string word in new[]{"true", "false", "null"})
                if (s.Substring(p).StartsWith(word, StringComparison.Ordinal))
                {
                    p += word.Length;
                    return word == "null" ? null : (Json58)(word == "true");
                }

            int start = p;
            while (p < s.Length && "-+0123456789.eE".IndexOf(s[p]) >= 0)
                p++;
            if (start == p)
                throw new ArgumentException("JSON token");
            return double.Parse(s.Substring(start, p - start), CultureInfo.InvariantCulture);
        }
    }

    public sealed class Obj58 : Json58
    {
        public Obj58()
        {
            fields = new Dictionary<string, Json58>(StringComparer.Ordinal);
        }

        public new static Obj58 Parse(string text)
        {
            return (Obj58)Json58.Parse(text);
        }
    }

    public sealed class Arr58 : Json58
    {
        public Arr58(params object[] values)
        {
            items = new List<Json58>();
            if (values.Length == 1 && values[0] is IEnumerable && !(values[0] is string) && !(values[0] is Json58))
            {
                foreach (var v in (IEnumerable)values[0])
                    Add(Wrap(v));
            }
            else
                foreach (var v in values)
                    Add(Wrap(v));
        }
    }

    // Small hash-only state snapshots. One native serialization per dirty object.
    public static class State58
    {
        public static string Hash(byte[] b)
        {
            using (var h = SHA256.Create())
                return BitConverter.ToString(h.ComputeHash(b)).Replace("-", "").ToLowerInvariant();
        }

        public static Obj58 Memory()
        {
            return new Obj58{["utc"] = DateTime.UtcNow.ToString("O"), ["GetTotalAllocatedMemoryLong"] = Profiler.GetTotalAllocatedMemoryLong(), ["GetTotalReservedMemoryLong"] = Profiler.GetTotalReservedMemoryLong(), ["GetMonoUsedSizeLong"] = Profiler.GetMonoUsedSizeLong()};
        }

        public static Obj58 Read()
        {
            var dirty = new Arr58();
            long serializedBytes = 0;
            var objects = Resources.FindObjectsOfTypeAll<UnityEngine.Object>().Where(o => o && EditorUtility.IsPersistent(o) && EditorUtility.IsDirty(o)).Where(o => AssetDatabase.GetAssetPath(o).StartsWith("Assets/") || AssetDatabase.GetAssetPath(o).StartsWith("ProjectSettings/")).OrderBy(o => AssetDatabase.GetAssetPath(o)).ThenBy(o => o.GetEntityId().ToString());
            foreach (var o in objects)
            {
                string native = EditorJsonUtility.ToJson(o);
                byte[] bytes = System.Text.Encoding.UTF8.GetBytes(native);
                serializedBytes += bytes.Length;
                dirty.Add(new Obj58{["path"] = AssetDatabase.GetAssetPath(o), ["guid"] = AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(o)), ["entityId"] = o.GetEntityId().ToString(), ["type"] = o.GetType().FullName, ["sha256"] = Hash(bytes), ["bytes"] = bytes.Length});
            // Neither full JSON nor byte copies enter the snapshot/return value.
            }

            var active = SceneManager.GetActiveScene();
            var scenes = new Arr58();
            foreach (var s in Enumerable.Range(0, SceneManager.sceneCount).Select(i => SceneManager.GetSceneAt(i)))
                scenes.Add(new Obj58{["path"] = s.path, ["dirty"] = s.isDirty, ["loaded"] = s.isLoaded, ["active"] = s == active, ["roots"] = new Arr58(s.isLoaded ? s.GetRootGameObjects().Select(o => o.GetEntityId().ToString()).OrderBy(v => v) : Enumerable.Empty<string>())});
            var files = new Arr58();
            foreach (var path in dirty.Select(r => (string)r["path"]).Concat(scenes.Select(s => (string)s["path"])).SelectMany(p => new[]{p, p + ".meta"}).Distinct().OrderBy(p => p).Where(File.Exists))
                files.Add(new Obj58{["path"] = path, ["sha256"] = Hash(File.ReadAllBytes(path))});
            var textures = new Arr58(Resources.FindObjectsOfTypeAll<Texture2D>().Select(t => t.GetEntityId().ToString()).OrderBy(v => v));
            var rts = new Arr58(Resources.FindObjectsOfTypeAll<RenderTexture>().Select(t => t.GetEntityId().ToString()).OrderBy(v => v));
            return new Obj58{["utc"] = DateTime.UtcNow.ToString("O"), ["project"] = Application.dataPath, ["version"] = Application.unityVersion, ["domain"] = AppDomain.CurrentDomain.Id, ["playing"] = EditorApplication.isPlaying, ["paused"] = EditorApplication.isPaused, ["transitioning"] = EditorApplication.isPlayingOrWillChangePlaymode, ["compiling"] = EditorApplication.isCompiling, ["updating"] = EditorApplication.isUpdating, ["dirty"] = dirty, ["serializedBytes"] = serializedBytes, ["files"] = files, ["scenes"] = scenes, ["texture2DIds"] = textures, ["rtIds"] = rts, ["buildScenes"] = new Arr58(EditorBuildSettings.scenes.Select(s => (s.enabled ? "1" : "0") + "\t" + s.path + "\t" + s.guid))};
        }

        public static string[] Changes(Obj58 a, Obj58 b)
        {
            return new[]{"project", "version", "domain", "playing", "paused", "transitioning", "compiling", "updating", "dirty", "files", "scenes", "buildScenes"}.Where(k => !Json58.DeepEquals(a[k], b[k])).ToArray();
        }

        public static void RequireEdit(Obj58 state)
        {
            if ((bool)state["playing"] || (bool)state["transitioning"] || (bool)state["compiling"] || (bool)state["updating"])
                throw new InvalidOperationException("Stable Edit state required");
        }
    }

    // Pure CPU port of source-palette54. No model/material-role constants or Unity state.
    public static class SourcePalette58
    {
        public sealed class Source
        {
            public string modelSHA256, imageSHA256, uvOrigin = "top-left", encoding = "srgb8";
            public int materialId;
            public double[] factorLinear;
        }

        public sealed class Sample
        {
            public string id, imageSHA256;
            public int materialId, primitiveId, triangle;
            public double[] uv;
            public int[] texel, rgba8;
            public double weight;
        }

        public sealed class Family
        {
            public string id, domainId;
            public Source source;
            public Sample[] samples;
        }

        public sealed class Colour
        {
            public Sample sample;
            public double[] linear, lab;
            public int[] rgb8;
            public double weight;
        }

        public sealed class Reference
        {
            public int[] rgb8;
            public double[] lab;
            public Sample sample;
            public double cost;
            public int sampleCount;
        }

        public sealed class Settings
        {
            public int count;
            public double darkLRatio, darkCRatio, gamma, intervalScale;
        }

        public sealed class Palette
        {
            public int[][] rgb8;
            public double[] targetL, requestedC, usedC, actualL;
            public bool[] gamutReduced;
            public int duplicates, LReversals;
        }

        public static bool Finite(double v)
        {
            return !double.IsNaN(v) && !double.IsInfinity(v);
        }

        static void Require(bool ok, string message)
        {
            if (!ok)
                throw new ArgumentException(message);
        }

        public static double Decode(double x)
        {
            return x <= .04045 ? x / 12.92 : Math.Pow((x + .055) / 1.055, 2.4);
        }

        public static double Encode(double x)
        {
            return x <= .0031308 ? 12.92 * x : 1.055 * Math.Pow(x, 1.0 / 2.4) - .055;
        }

        static double Cbrt(double x)
        {
            return Math.Sign(x) * Math.Pow(Math.Abs(x), 1.0 / 3);
        }

        static int RGB8(double x)
        {
            return (int)Math.Floor(255 * Encode(x) + .5);
        }

        public static double[] LabLinear(double[] c)
        {
            double r = c[0], g = c[1], b = c[2];
            double l = Cbrt(.4122214708 * r + .5363325363 * g + .0514459929 * b), m = Cbrt(.2119034982 * r + .6806995451 * g + .1073969566 * b), s = Cbrt(.0883024619 * r + .2817188376 * g + .6299787005 * b);
            return new[]{.2104542553 * l + .793617785 * m - .0040720468 * s, 1.9779984951 * l - 2.428592205 * m + .4505937099 * s, .0259040371 * l + .7827717662 * m - .808675766 * s};
        }

        public static double[] LabRGB(int[] rgb)
        {
            return LabLinear(rgb.Select(v => Decode(v / 255.0)).ToArray());
        }

        public static double[] LinearLch(double L, double C, double h)
        {
            double a = C * Math.Cos(h), b = C * Math.Sin(h), l = Math.Pow(L + .3963377774 * a + .2158037573 * b, 3), m = Math.Pow(L - .1055613458 * a - .0638541728 * b, 3), s = Math.Pow(L - .0894841775 * a - 1.291485548 * b, 3);
            return new[]{4.0767416621 * l - 3.3077115913 * m + .2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - .3413193965 * s, -.0041960863 * l - .7034186147 * m + 1.707614701 * s};
        }

        static bool Valid(double[] v)
        {
            return v.All(x => x >= -1e-9 && x <= 1 + 1e-9);
        }

        public static int[] Gamut(double L, double C, double h, out double usedC)
        {
            usedC = C;
            var v = LinearLch(L, C, h);
            if (!Valid(v))
            {
                double lo = 0, hi = C;
                for (int i = 0; i < 28; i++)
                {
                    double mid = (lo + hi) / 2;
                    if (Valid(LinearLch(L, mid, h)))
                        lo = mid;
                    else
                        hi = mid;
                }

                usedC = lo;
                v = LinearLch(L, usedC, h);
            }

            return v.Select(x => RGB8(Math.Max(0, Math.Min(1, x)))).ToArray();
        }

        public static Colour[] SourceColours(Family f)
        {
            Require(f != null && f.source != null && f.samples != null, "Explicit source family required");
            var s = f.source;
            Require(!string.IsNullOrEmpty(s.modelSHA256) && !string.IsNullOrEmpty(s.imageSHA256) && s.uvOrigin == "top-left" && s.encoding == "srgb8", "Original source/encoding required");
            Require(s.factorLinear != null && s.factorLinear.Length == 4 && s.factorLinear.All(x => Finite(x) && x >= 0 && x <= 1), "Linear material factor required");
            var result = new List<Colour>();
            foreach (var v in f.samples)
            {
                Require(v.materialId == s.materialId && v.imageSHA256 == s.imageSHA256, "Source family mismatch");
                Require(!string.IsNullOrEmpty(v.id) && v.uv != null && v.uv.Length == 2 && v.uv.All(Finite) && v.texel != null && v.texel.Length == 2, "Original UV/texel missing");
                Require(v.rgba8 != null && v.rgba8.Length == 4 && v.rgba8.All(x => x >= 0 && x <= 255) && v.weight > 0 && Finite(v.weight), "Invalid source sample");
                double weight = v.weight * v.rgba8[3] / 255.0 * s.factorLinear[3];
                if (weight <= 0)
                    continue;
                var linear = Enumerable.Range(0, 3).Select(i => Decode(v.rgba8[i] / 255.0) * s.factorLinear[i]).ToArray();
                result.Add(new Colour{sample = v, linear = linear, lab = LabLinear(linear), rgb8 = linear.Select(RGB8).ToArray(), weight = weight});
            }

            return result.ToArray();
        }

        public static Reference ExtractReference(Family f)
        {
            var samples = SourceColours(f);
            Require(samples.Length > 0, "No visible source samples");
            Colour best = null;
            double cost = double.PositiveInfinity;
            foreach (var c in samples)
            {
                double sum = 0;
                foreach (var s in samples)
                {
                    double q = 0;
                    for (int i = 0; i < 3; i++)
                        q += (s.lab[i] - c.lab[i]) * (s.lab[i] - c.lab[i]);
                    sum += s.weight * q;
                }

                // Stable original ASCII sample IDs in this provider; see portability limit.
                if (sum < cost || (sum == cost && (best == null || StringComparer.Ordinal.Compare(c.sample.id, best.sample.id) < 0)))
                {
                    best = c;
                    cost = sum;
                }
            }

            return new Reference{rgb8 = (int[])best.rgb8.Clone(), lab = (double[])best.lab.Clone(), sample = best.sample, cost = cost, sampleCount = samples.Length};
        }

        public static Palette MakePalette(Reference reference, Settings p)
        {
            Require(p.count >= 2 && p.count <= 256 && Finite(p.darkLRatio) && Finite(p.darkCRatio) && p.darkLRatio >= 0 && p.darkLRatio <= 1 && p.darkCRatio >= 0 && p.darkCRatio <= 1 && p.gamma > 0 && Finite(p.gamma) && p.intervalScale >= 0 && Finite(p.intervalScale), "Invalid palette settings");
            var lab = LabRGB(reference.rgb8);
            double L0 = lab[0], C0 = Math.Sqrt(lab[1] * lab[1] + lab[2] * lab[2]), h = Math.Atan2(lab[2], lab[1]);
            var result = new Palette{rgb8 = new int[p.count][], targetL = new double[p.count], requestedC = new double[p.count], usedC = new double[p.count], actualL = new double[p.count], gamutReduced = new bool[p.count]};
            for (int k = 0; k < p.count; k++)
            {
                double t = Math.Pow((double)k / (p.count - 1), p.gamma), L = L0 + p.intervalScale * (L0 * (p.darkLRatio + (1 - p.darkLRatio) * t) - L0), C = C0 + p.intervalScale * (C0 * (p.darkCRatio + (1 - p.darkCRatio) * t) - C0);
                Require(L >= 0 && L <= 1 && C >= 0, "Palette interval exceeds L/C domain");
                result.targetL[k] = L;
                result.requestedC[k] = C;
                if (k == p.count - 1 || p.intervalScale == 0)
                {
                    result.rgb8[k] = (int[])reference.rgb8.Clone();
                    result.usedC[k] = C0;
                }
                else
                {
                    double used;
                    result.rgb8[k] = Gamut(L, C, h, out used);
                    result.usedC[k] = used;
                    result.gamutReduced[k] = C - used > 1e-7;
                }

                result.actualL[k] = LabRGB(result.rgb8[k])[0];
                if (k > 0 && result.actualL[k] < result.actualL[k - 1] - 1e-9)
                    result.LReversals++;
            }

            result.duplicates = p.count - result.rgb8.Select(v => string.Join(",", v)).Distinct().Count();
            return result;
        }

        public static int ShadeIndex(double g, double[] thresholds)
        {
            Require(Finite(g) && thresholds != null && thresholds.All(Finite), "Finite shade inputs required");
            float x = (float)g;
            Require(!float.IsInfinity(x), "Shade exceeds Float32");
            int k = 0;
            float previous = float.NegativeInfinity;
            foreach (double value in thresholds)
            {
                float cut = (float)value;
                Require(!float.IsInfinity(cut) && cut > previous, "Sorted distinct Float32 thresholds required");
                if (x >= cut)
                    k++;
                previous = cut;
            }

            return k;
        }

        public static int[] Resolve(Palette p, int k)
        {
            Require(k >= 0 && k < p.rgb8.Length, "Unbound shade index");
            return (int[])p.rgb8[k].Clone();
        }
    }

