                {
                    int tri = j * (ss[d].triangleCount - 1) / 31;
                    Vector2 p = (uv[ix[tri * 3]] + uv[ix[tri * 3 + 1]] + uv[ix[tri * 3 + 2]]) / 3;
                    p = Vector2.Scale(p, draw.scale) + draw.offset;
                    Color32 c;
                    Vector2Int texel;
                    string reason;
                    if (!provider.TryReadSourcePoint(d, tri, p, out c, out texel, out reason))
                        throw new InvalidOperationException("Reference source missing: " + reason);
                    samples.Add(new SourcePalette58.Sample{id = "d" + d.ToString("D2") + "-t" + tri.ToString("D6"), materialId = ss[d].materialId, primitiveId = (int)bind["gltfPrimitive"], triangle = tri, imageSHA256 = (string)bind["imageSHA256"], uv = new[]{(double)p.x, 1 - (double)p.y}, texel = new[]{texel.x, draw.texture.height - 1 - texel.y}, rgba8 = new[]{(int)c.r, c.g, c.b, c.a}, weight = 1});
                }

                var family = new SourcePalette58.Family{id = ss[d].sourceFamilyId, domainId = ss[d].sourceFamilyId, source = new SourcePalette58.Source{modelSHA256 = (string)specs["modelSHA256"], imageSHA256 = (string)bind["imageSHA256"], materialId = ss[d].materialId, factorLinear = new[]{(double)draw.factor.r, draw.factor.g, draw.factor.b, draw.factor.a}}, samples = samples.ToArray()};
                var reference = SourcePalette58.ExtractReference(family);
                var settings = new SourcePalette58.Settings{count = count, darkLRatio = .55, darkCRatio = .6, gamma = 1, intervalScale = 1};
                var palette = SourcePalette58.MakePalette(reference, settings);
                palettes[d] = palette;
                int first = rgbWords.Count, cutStart = thresholds.Count;
                foreach (var colour in palette.rgb8)
                    rgbWords.Add(new U4((uint)colour[0], (uint)colour[1], (uint)colour[2], 255));
                for (int k = 0; k < count - 1; k++)
                    thresholds.Add((k + .5f) / (count - 1));
                familyWords.Add(new U4((uint)first, (uint)count, (uint)cutStart, (uint)count - 1));
                paletteRows.Add(new Obj58{["draw"] = d, ["legacyRole"] = role, ["binding"] = bind, ["family"] = SourceJson58.Family(family), ["reference"] = SourceJson58.Reference(reference), ["settings"] = SourceJson58.Settings(settings), ["palette"] = SourceJson58.Palette(palette)});
            }

            report["palettes"] = paletteRows;
            report["scopeClassifier"] = "Existing runtime role 11..14; source identity independently validated by full UV/index hashes";
            report["paletteSettingsAreDiagnostic"] = true;
            report["surfaceShadeSteps"] = count;
            report["selectionMapping"] = new Arr58(roleDraw.Select(p => new Obj58{["role"] = p.Key, ["draw"] = p.Value}));
            var rgb = Buffer(rgbWords.ToArray(), 16);
            var cuts = Buffer(thresholds.ToArray(), 4);
            var families = Buffer(familyWords.ToArray(), 16);
            var roles = Buffer(roleFamily, 4);
            // Equal, current-frame capture policy for both arms. No resetHistory/RenderPose.
            f.capturePending = true;
            if (n.host.head)
                n.host.head.capturePending = true;
            n.host.RenderFrame();
            report["controlPose"] = Pose(n);
            Save("control-rendered");
            var baseFull = Read(n.output.rt);
            var baseMeta = Read(f.preparedMeta.rt);
            var baseUV = Read(f.preparedUV.rt);
            var baseOwner = Read(f.owner.rt);
            var baseLocal = Read(f.colour.rt);
            var baseNativeOwner = Read(n.owner.rt);
            Raw("CONTROL_FULL60.float4", baseFull);
            Raw("CONTROL_META60.float4", baseMeta);
            Raw("CONTROL_UV60.float4", baseUV);
            Raw("CONTROL_OWNER60.float4", baseOwner);
            Raw("CONTROL_LOCAL60.float4", baseLocal);
            Raw("CONTROL_NATIVE_OWNER60.float4", baseNativeOwner);
            PNG("CONTROL_FULL60.png", baseFull, 960, 544);
            var shader = AssetDatabase.LoadAssetAtPath<Shader>(Probe + "LegacySignals60.shader");
            var independent = AssetDatabase.LoadAssetAtPath<Shader>(Probe + "Independent60.shader");
            var original = AssetDatabase.LoadAssetAtPath<ComputeShader>(Probe + "RestoreStyle60.compute");
            foreach (var v in new[]{f, n.host.head}.Where(v => v))
            {
                var state = new Saved{f = v, legacy = v.legacySignalsMats, independent = v.independentMats, restore = v.restoreStyle};
                saved.Add(state);
                v.legacySignalsMats = (Material[])state.legacy.Clone();
                v.independentMats = (Material[])state.independent.Clone();
                for (int d = 0; d < ss.Length; d++)
                    if (palettes[d] != null)
                    {
                        var m = new Material(state.legacy[d])
                        {shader = shader, hideFlags = HideFlags.HideAndDontSave};
                        materials.Add(m);
                        Bind(m, d, rgb, cuts, families);
                        v.legacySignalsMats[d] = m;
                        var q = new Material(state.independent[d])
                        {shader = independent, hideFlags = HideFlags.HideAndDontSave};
                        materials.Add(q);
                        Bind(q, d, rgb, cuts, families);
                        v.independentMats[d] = q;
                    }

                var cs = UnityEngine.Object.Instantiate(original);
                cs.hideFlags = HideFlags.HideAndDontSave;
                computes.Add(cs);
                int kernel = cs.FindKernel("ApplyShadeBoundary");
                cs.SetBuffer(kernel, "_RoleFamily60", roles);
                cs.SetBuffer(kernel, "_SourcePalette54RGB8", rgb);
                cs.SetBuffer(kernel, "_SourcePalette54Families", families);
                v.restoreStyle = cs;
            }

            f.capturePending = true;
            if (n.host.head)
                n.host.head.capturePending = true;
            n.host.RenderFrame();
            report["candidatePose"] = Pose(n);
            report["poseAndGeometryExact"] = Json58.DeepEquals(report["controlPose"], report["candidatePose"]);
            Save("candidate-rendered");
            var candidateFull = Read(n.output.rt);
            var candidateMeta = Read(f.preparedMeta.rt);
            var candidateUV = Read(f.preparedUV.rt);
            var candidateOwner = Read(f.owner.rt);
            var candidateLocal = Read(f.colour.rt);
            var candidateNativeOwner = Read(n.owner.rt);
            Raw("CANDIDATE_FULL60.float4", candidateFull);
            Raw("CANDIDATE_META60.float4", candidateMeta);
            Raw("CANDIDATE_UV60.float4", candidateUV);
            Raw("CANDIDATE_OWNER60.float4", candidateOwner);
            Raw("CANDIDATE_LOCAL60.float4", candidateLocal);
            Raw("CANDIDATE_NATIVE_OWNER60.float4", candidateNativeOwner);
            PNG("CANDIDATE_FULL60.png", candidateFull, 960, 544);
            int x0 = 480, y0 = 272, x1 = 0, y1 = 0;
            for (int i = 0; i < candidateMeta.Length; i++)
            {
                int role = Mathf.RoundToInt(candidateMeta[i].g) - 1;
                if (candidateMeta[i].r > 0 && role >= 0 && role < 16 && roleFamily[role] > 0)
                {
                    int x = i % 480, y = i / 480;
                    x0 = Math.Min(x0, x);
                    y0 = Math.Min(y0, y);
                    x1 = Math.Max(x1, x + 1);
                    y1 = Math.Max(y1, y + 1);
                }
            }

            if (x0 >= x1 || y0 >= y1)
                throw new InvalidOperationException("No candidate visible hair provenance");
            var roi = new RectInt(x0, y0, x1 - x0, y1 - y0);
            report["hairRectBottomLeft"] = new Arr58(new[]{roi.x, roi.y, roi.width, roi.height});
            var srcView = n.host.head ? n.host.head : f;
            Vector2Int offset = n.host.head ? n.host.offset : Vector2Int.zero;
            var sr = new RectInt(roi.x - offset.x, roi.y - offset.y, roi.width, roi.height);
            if (sr.x < 0 || sr.y < 0 || sr.xMax > 480 || sr.yMax > 272)
                throw new InvalidOperationException("Head/source ROI mismatch");
            var sourceClass = Read(srcView.style480[3].rt, sr);
            var sourceMeta = Read(srcView.motion.raw[5].rt, sr);
            var sourceUV = Read(srcView.motion.raw[6].rt, sr);
            var sourceInitial = Read(srcView.style480[0].rt, sr);
            var sourceMask = Read(srcView.shadeMask480.rt, sr);
            var map = srcView.actionMap.GetPixels();
            Raw("SELECTED_SOURCE_CLASS60.float4", sourceClass);
            Raw("SELECTED_SOURCE_META60.float4", sourceMeta);
            Raw("SELECTED_SOURCE_UV60.float4", sourceUV);
            Raw("SELECTED_SOURCE_INITIAL60.float4", sourceInitial);
            Raw("SELECTED_SOURCE_MASK60.float4", sourceMask);
            var cells = new Arr58();
            int unknown = 0, known = 0;
            for (int yy = 0; yy < roi.height; yy++)
                for (int xx = 0; xx < roi.width; xx++)
                {
                    int i = (roi.y + yy) * 480 + roi.x + xx, j = yy * roi.width + xx;
                    var meta = candidateMeta[i];
                    int role = Mathf.RoundToInt(meta.g) - 1;
                    if (meta.r <= 0 || role < 0 || role >= 16 || roleFamily[role] == 0)
                        continue;
                    int draw = roleDraw[role], tri = Mathf.RoundToInt(meta.a) - 1;
                    Color32 colour;
                    Vector2Int texel;
                    string reason;
                    bool bound = provider.TryReadSourcePoint(draw, tri, new Vector2(candidateUV[i].r, candidateUV[i].g), out colour, out texel, out reason);
                    if (bound)
                        known++;
                    else
                        unknown++;
                    bool centre = Math.Abs(meta.g - sourceMeta[j].g) < .01 && Math.Abs(meta.a - sourceMeta[j].a) < .01 && Math.Abs(candidateUV[i].r - sourceUV[j].r) < 1e-5 && Math.Abs(candidateUV[i].g - sourceUV[j].g) < 1e-5;
                    var row = new Obj58{["x"] = roi.x + xx, ["yBottom"] = roi.y + yy, ["draw"] = draw, ["materialId"] = ss[draw].materialId, ["triangle"] = tri, ["uv"] = new Arr58(new[]{candidateUV[i].r, candidateUV[i].g}), ["sourceKnown"] = bound, ["sourceFailure"] = reason, ["sourceRGBA8"] = bound ? new Arr58(new[]{(int)colour.r, colour.g, colour.b, colour.a}) : null, ["texelUnityBottom"] = bound ? new Arr58(new[]{texel.x, texel.y}) : null, ["owner"] = C(candidateOwner[i]), ["selectedMeta"] = C(meta), ["centreSourceExact"] = centre, ["g"] = centre ? (Json58)sourceClass[j].g : null, ["q"] = candidateUV[i].b, ["centreClass"] = C(sourceClass[j]), ["centreInitial"] = C(sourceInitial[j]), ["centreMask"] = C(sourceMask[j]), ["controlRGBLinear"] = C(baseLocal[i]), ["candidateRGBLinear"] = C(candidateLocal[i])};
                    cells.Add(row);
                }

            report["knownVisibleHairSourceCells"] = known;
            report["unknownVisibleHairSourceCells"] = unknown;
            report["cells"] = cells;
            report["capturePolicy"] = "Both arms capturePending=true once, no resetHistory, no RenderPose; static-frame comparison only";
            report["cleanBackingReason"] = "Not collected: this hair-only candidate does not supply a proven source-aligned clean eye backing pass";
            Save("comparison-captured");
        }
    }

